  "helpTitle": "How It Works",
  "helpSubtitle": "A complete guide — filters, games, tools, and team mode.",
  "btnGotIt": "Got it — let's play!",
  "helpSecFilters": "Filters",
  "helpTipFilters1": "<strong>Level, Theme, Type</strong> — use these filters to narrow the word pool before starting any game. Select multiple values from any picker; only words matching <em>all active filters</em> will appear.",
  "helpTipFilters2": "<strong>Filters carry over</strong> — when you navigate from game to game, your filter selections stay in place. Use <strong>Reset</strong> to clear everything back to \"All\".",
  "helpTipFilters3": "<strong>Multiple themes per word</strong> — a word can belong to several themes (e.g. \"Emotions, Character\"). It will appear whenever any of its themes is selected.",
  "helpSecVocab": "Vocabulary Games",
  "matchPairsLabel": "Pairs:",
  "helpCardDefMatchTitle": "Definition Match",
  "helpCardDefMatchDesc": "Flip cards to pair each word with its correct definition. Click a word card, then its matching definition card. All pairs must be found to win.",
  "helpCardHangmanTitle": "Hangman",
  "helpCardHangmanDesc": "Guess the hidden word letter by letter. Choose your number of allowed mistakes (4–12). Use <strong>Clue</strong> to reveal the definition.",
  "helpCardScrambleTitle": "Scrambled Word",
  "helpCardScrambleDesc": "The word's letters are shuffled. Click letters to build your answer, use <strong>Clue</strong> for a letter hint, then submit.",
  "helpCardWordQuestTitle": "Word Quest",
  "helpCardWordQuestDesc": "A definition is shown. Unlock up to 4 progressive clues (synonyms, letter hints…) to narrow it down, then type your guess.",
  "helpCardPhoneticTitle": "Phonetic Guess",
  "helpCardPhoneticDesc": "An IPA phonetic transcription is shown. Identify the word it represents — pick from 4 choices or type the answer directly.",
  "helpCardSynAntTitle": "Synonyms & Antonyms",
  "helpCardSynAntDesc": "A word is shown — find its synonym or antonym. Toggle between Synonym, Antonym, or Both modes. Multiple choice or free typing.",
  "helpSecGrammar": "Grammar Games",
  "helpCardSentenceTitle": "Sentence Builder",
  "helpCardSentenceDesc": "Reconstruct a scrambled sentence by clicking words in the correct order. The target structure is shown; use <strong>Clue</strong> to reveal the next word.",
  "helpCardGapFillTitle": "Gap Fill",
  "helpCardGapFillDesc": "A sentence has one word removed. Type the missing word. Filter by grammar type (Relatives, Conditionals…) for targeted practice.",
  "helpCardFindErrorTitle": "Find the Error",
  "helpCardFindErrorDesc": "Spot the grammatical mistake in a sentence. Two modes: <strong>Spot</strong> (choose correct vs erroneous) or <strong>Rewrite</strong> (correct the sentence yourself).",
  "helpCardDictationTitle": "Dictation",
  "helpCardDictationDesc": "A text is read aloud. Type what you hear, word by word. Choose Easy (10% words hidden), Medium (50%), or Hard (90%) difficulty.",
  "helpSecTools": "Tools",
  "helpCardGrammarPracticeTitle": "Grammar Practice",
  "helpCardGrammarPracticeDesc": "A reference library of grammar rules — formulas, signals words, common mistakes, and tips. Filter by category or level.",
