  "lcPillsHelpBtnTitle": "Explain activities and interaction modes",
  "lcPillsGuideTitle": "Phase Activities & Modes Guide",
  "lcPillsGuideSub": "A beginner's guide to structuring effective lesson phases and student grouping.",
  "lcPillsGuideTip": "Tip: Hover over any activity or mode pill in the timeline to see a quick reminder.",
  "lcTabActivities": "Activity Types",
  "lcTabModes": "Interaction Modes",
  "lcPillWhenToUse": "When to use:",
  "lcPillPedagogy": "Pedagogical focus:",
  "lcActWarmUpDesc": "Quick starter task (3–5 min) at the beginning of the lesson to engage students, review prior learning, and settle the classroom into a focused mindset.",
  "lcAct_warm_up_when": "First 5 minutes; entrance ticket, retrieval practice, settling the class.",
  "lcActDirectInstructionDesc": "Explicit teacher presentation of new concepts, worked examples, rules, or procedural modeling. Kept concise (10–15 min) to prevent cognitive overload.",
  "lcAct_direct_instruction_when": "Introducing new learning targets, formulas, methods, or key concepts.",
  "lcActGuidedPracticeDesc": "Students practice the new skill with active teacher scaffolding, step-by-step guidance, and immediate feedback ('I do, We do, You do').",
  "lcAct_guided_practice_when": "Directly following instruction to build confidence and catch errors early.",
  "lcActIndependentWorkDesc": "Students apply learning autonomously on exercises, reading, writing, or problem-solving at their own pace without teacher intervention.",
  "lcAct_independent_work_when": "After guided practice once concepts are secure; allows teacher to circulate and differentiate.",
  "lcActGroupActivityDesc": "Collaborative peer task where students solve complex problems, build projects, conduct experiments, or share assigned roles.",
  "lcAct_group_activity_when": "Multi-step investigations, jigsaw tasks, project-based work, and creative problem solving.",
  "lcActDiscussionDesc": "Structured dialogue, Socratic seminar, debate, or fishbowl where students articulate ideas, evaluate claims, and justify viewpoints.",
  "lcAct_discussion_when": "Analyzing dilemmas, evaluating arguments, exploring controversies, and developing oral fluency.",
  "lcActAssessmentDesc": "Formative check for understanding (exit quiz, mini-whiteboards, digital poll) to evaluate student mastery and diagnose gaps.",
  "lcAct_assessment_when": "Mid-lesson checkpoint, pre-transition assessment, or diagnosing remediation needs.",
  "lcActPlenaryDesc": "Lesson synthesis (5–10 min) to review core takeaways, revisit initial learning goals, and collect student reflections or exit tickets.",
  "lcAct_plenary_when": "Final 5–10 minutes of class to lock in learning and inform the next lesson plan.",
  "lcModeWholeClassDesc": "All students participate together as a single collective audience (e.g. read-aloud, shared video, group brainstorming, or community circle).",
  "lcMode_whole_class_when": "Shared community focus, class instructions, common cultural or media reference.",
  "lcModeTeacherLedDesc": "Teacher leads from the front at the board or screen, explaining, orchestrating questioning, and modeling procedures.",
  "lcMode_teacher_led_when": "Direct instruction, explaining complex concepts, demonstrating worked examples.",
  "lcModeIndividualDesc": "Each student works independently and silently at their own desk, building deep focus and individual accountability.",
  "lcMode_individual_when": "Silent reading, individual writing, formative tests, practice exercises.",
  "lcModePairsDesc": "Students collaborate in pairs (Turn & Talk, peer review, dialoguing). Maximizes oral participation and low-anxiety peer support.",
  "lcMode_pairs_when": "Turn and talk, peer feedback, vocabulary drills, practicing foreign language dialogue.",
  "lcModeSmallGroupsDesc": "Small teams of 3 to 4 students work cooperatively with structured roles (spokesperson, timekeeper, recorder, facilitator).",
  "lcMode_small_groups_when": "Project tasks, collaborative problem solving, complex inquiries, cooperative teams.",
  "lcModeStationsDesc": "Classroom is split into timed activity centers or learning stations; small groups circulate from station to station.",
  "lcMode_stations_when": "Multi-modal learning, science lab circuits, differentiated skill stations, art/reading corners.",
