  "lcImportDesc": "Select a CSV, XLSX, or JSON file containing curriculum standards with columns: Code, Title, Category, Subcategory, Level, Description, Tags, Comments.",
  "mdbHelp_descriptors_id": "Unique identifier for this standard (e.g., 'sci-bio-01' or a UUID). Used internally for linking to lesson plans.",
  "mdbHelp_descriptors_code": "Official curriculum or syllabus code (e.g., 'SCI.BIO.01', 'CEFR.B1.SPK.02', 'MATH.ALG.04'). Displayed on lesson tags.",
