  "mdbHelp_descriptors_subCategory": "Sub-strand, unit, or topic area (e.g., 'Ecosystems', 'Interactive Discourse', 'Linear Functions').",
  "mdbHelp_descriptors_yearLevel": "Target year or grade level (e.g., 'Year 9', 'Grade 10', 'Seconde', '3ème', 'All Levels').",
  "mdbHelp_descriptors_semester": "Target term or semester (e.g., 'S1', 'S2', 'Term 1', 'Full Year').",
  "mdbHelp_descriptors_level": "Taxonomy tier, CEFR level, or competency band (e.g., 'A2', 'B1', 'B2', 'Foundational', 'Advanced', 'Tier 2').",
